-- ============================================================
-- SCONT – PDI: seed do modelo "Assistente de Departamento Pessoal" e do PDI de exemplo
-- Gerado por Projeto PDI/tools/gerar-seed.js a partir de js/textos.js (NÃO editar à mão).
-- Pré-requisito: _sql/schema_pdi.sql. Idempotente.
-- O PDI de exemplo fica sem colaborador_user_id: o admin vincula o usuário depois.
-- ============================================================
DO $seed$
DECLARE
    v_modelo UUID;
    v_pdi UUID;
BEGIN
    SELECT id INTO v_modelo FROM public.pdi_modelos WHERE cargo_setor = 'Assistente de Departamento Pessoal' ORDER BY versao DESC LIMIT 1;
    IF v_modelo IS NULL THEN
        INSERT INTO public.pdi_modelos (cargo_setor, conteudo)
        VALUES ('Assistente de Departamento Pessoal', '{"objetivo":["Direcionar o desenvolvimento profissional, fortalecendo o domínio das rotinas de DP, a autonomia operacional, a comunicação e a qualidade das entregas. O plano considera as competências da função, o perfil comportamental e os resultados observados na prática.","O acompanhamento será realizado com participação da colaboradora, orientação do gestor e acompanhamento da Diretoria. Cada trimestre permitirá registrar avanços, revisar prioridades e estabelecer o próximo ciclo."],"apoio_scont":"acesso ao sistema, procedimentos, exemplos de conferência e tempo para orientação técnica.","perfil_esperado":[{"competencia":"Organização e atenção","evidencia":"Orientação a processos e detalhes","direcionamento":"Consolidado no perfil; confirmar nas entregas","status":"consolidado"},{"competencia":"Estabilidade e Colaboração","evidencia":"Paciência, escuta e cooperação","direcionamento":"Consolidado no perfil; manter","status":"consolidado"},{"competencia":"Abertura a mudanças","evidencia":"Oportunidade expressa","direcionamento":"Em desenvolvimento; praticar novos fluxos","status":"em_desenvolvimento"},{"competencia":"Visibilidade profissional","evidencia":"Oportunidade expressa","direcionamento":"Em desenvolvimento; apresentar entregas","status":"em_desenvolvimento"},{"competencia":"Comunicação assertiva","evidencia":"Estilo diplomático e busca de consenso","direcionamento":"Em desenvolvimento; comunicar riscos objetivamente","status":"em_desenvolvimento"},{"competencia":"Autonomia e iniciativa","evidencia":"Sem medida direta no relatório","direcionamento":"Prioritário no plano; avaliar na prática","status":"prioritario"},{"competencia":"Agilidade e prioridades","evidencia":"Sem medida direta no relatório","direcionamento":"Em desenvolvimento; avaliar na prática","status":"em_desenvolvimento"}],"tecnicas":[{"competencia":"Sistema Domínio","pratica":"Treinamento guiado, ambiente de prática e roteiro de uso","meta":"Executar rotinas básicas com acompanhamento"},{"competencia":"Onboarding do cliente","pratica":"Checklist documental, particularidades CCT etc","meta":"Executar o ciclo de forma completa"},{"competencia":"Admissões e cadastros","pratica":"Checklist documental e execução supervisionada","meta":"Concluir processo e identificar pendências"},{"competencia":"Ponto e Benefícios","pratica":"Conferir registros e lançar informações orientadas","meta":"Aplicar checklist e explicar divergências"},{"competencia":"Férias e afastamentos","pratica":"Acompanhar fluxo, documentos e calendário","meta":"Executar etapas atribuídas com conferência"},{"competencia":"Folha e conferência","pratica":"Observar fechamento e conferir lançamentos selecionados","meta":"Identificar divergências e encaminhar correções"},{"competencia":"Obrigações e rescisões","pratica":"Conhecer fluxo, prazos e responsabilidades; acompanhar casos","meta":"Reconhecer documentos, riscos e limites da função"},{"competencia":"CCT e procedimentos","pratica":"Estudar regras aplicáveis aos clientes sob orientação","meta":"Localizar regras necessárias às rotinas"},{"competencia":"Organização documental","pratica":"Padronizar arquivos e controle de pendências","meta":"Manter rastreabilidade e agenda atualizada"}],"comportamentais":[{"competencia":"Autonomia","comportamento":"Resolver rotinas aprendidas e encaminhar exceções","acao":"Usar roteiro antes de pedir validação; registrar casos executados"},{"competencia":"Proatividade","comportamento":"Antecipar pendências e riscos de prazo","acao":"Revisar agenda diariamente; sinalizar pendência antes do vencimento"},{"competencia":"Comunicação assertiva","comportamento":"Informar situação, impacto e próximo passo","acao":"Praticar relatos objetivos; reunir exemplos de comunicação"},{"competencia":"Adaptabilidade","comportamento":"Aplicar mudanças com segurança","acao":"Testar novo fluxo com orientação; registrar aprendizado"},{"competencia":"Decisão e prioridades","comportamento":"Distinguir rotina, urgência e exceção","acao":"Definir prioridades com gestor; explicar critérios usados"},{"competencia":"Visibilidade","comportamento":"Compartilhar entregas e necessidades de apoio","acao":"Apresentar resumo semanal de concluídos, pendências e apoio"},{"competencia":"Visão Sistêmica","comportamento":"Acompanhar demandas de maior complexidade do setor","acao":"Orientando o time nos ajustes necessários a fim de evitar erros de processo"}],"acoes":[{"foco":"Avaliar domínio inicial e priorizar rotinas","responsaveis":"Gestor e colaboradora","dias":15,"recorrencia":null,"evidencia":"Níveis iniciais registrados e rotinas selecionadas"},{"foco":"Concluir trilha inicial do Domínio e praticar","responsaveis":"Colaboradora; apoio do gestor","dias":30,"recorrencia":null,"evidencia":"Roteiro aplicado em casos supervisionados"},{"foco":"Aplicar checklists de admissão, ponto e benefícios","responsaveis":"Colaboradora; conferência do gestor","dias":60,"recorrencia":null,"evidencia":"Amostras conferidas e correções registradas"},{"foco":"Praticar conferência de folha e controles de prazo","responsaveis":"Colaboradora; orientação do gestor","dias":90,"recorrencia":null,"evidencia":"Conferências documentadas e indicador de prazo"},{"foco":"Relatar entregas e antecipar pendências","responsaveis":"Colaboradora; feedback do gestor","dias":null,"recorrencia":"semanal","evidencia":"Resumo objetivo e exemplos de sinalização"},{"foco":"Avaliar evolução e pactuar próximo ciclo","responsaveis":"Colaboradora, gestor e Diretoria","dias":90,"recorrencia":null,"evidencia":"Avaliação trimestral e novas prioridades"}],"indicadores":[{"chave":"prazos","nome":"Prazos","formula":"entregas no prazo ÷ entregas previstas × 100","meta_texto":"≥ 95%; sinalizar riscos antes do vencimento","tipo_meta":"numerica","operador":">=","valor_meta":95,"evidencia":"Agenda e registro de entregas","calculo_automatico":null},{"chave":"retrabalho","nome":"Retrabalho","formula":"entregas corrigidas por erro de execução ÷ entregas conferidas × 100","meta_texto":"Reduzir frente à linha de base; definir percentual após medição","tipo_meta":"relativa_linha_base","operador":"<=","valor_meta":null,"evidencia":"Controle de correções e causas","calculo_automatico":null},{"chave":"conferencia","nome":"Conferência","formula":"rotinas com checklist completo ÷ rotinas que exigem checklist × 100","meta_texto":"100% das rotinas priorizadas","tipo_meta":"numerica","operador":"=","valor_meta":100,"evidencia":"Checklists datados","calculo_automatico":null},{"chave":"autonomia","nome":"Autonomia","formula":"rotinas consolidadas no nível 3 ÷ rotinas priorizadas × 100","meta_texto":"Medir no ciclo 1; pactuar avanço no ciclo 2","tipo_meta":"a_pactuar","operador":null,"valor_meta":null,"evidencia":"Registro de nível e amostras","calculo_automatico":"autonomia"},{"chave":"pendencias","nome":"Pendências","formula":"riscos sinalizados antes do prazo ÷ riscos identificados × 100","meta_texto":"100% dos riscos identificados","tipo_meta":"numerica","operador":"=","valor_meta":100,"evidencia":"Histórico de sinalizações","calculo_automatico":"pendencias"},{"chave":"controles","nome":"Controles","formula":"revisões semanais realizadas ÷ revisões previstas × 100","meta_texto":"100% das revisões previstas","tipo_meta":"numerica","operador":"=","valor_meta":100,"evidencia":"Agenda e controle atualizado","calculo_automatico":"controles"}],"ciclos":[{"numero":1,"periodo":"Meses 1 a 3","foco":"Integração, Domínio e rotinas básicas; execução assistida com qualidade"},{"numero":2,"periodo":"Meses 4 a 6","foco":"Consolidação técnica; autonomia nas rotinas validadas e redução de retrabalho"},{"numero":3,"periodo":"Meses 7 a 9","foco":"Consistência de prazos e qualidade; ampliação gradual de complexidade"},{"numero":4,"periodo":"Meses 10 a 12","foco":"Domínio do escopo da função; revisão de lacunas e possibilidades de desenvolvimento"}]}'::jsonb)
        RETURNING id INTO v_modelo;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.pdis WHERE colaborador_nome = 'Julia Costa Faria' AND data_inicio = '2026-10-07') THEN
        v_pdi := public.pdi_criar_a_partir_do_modelo(
            v_modelo, NULL, 'Julia Costa Faria', 'Assistente de Departamento Pessoal', '2026-09-08'::date,
            NULL, 'Brenna Costa', '2026-10-07'::date);
        UPDATE public.pdis
           SET contexto_desenvolvimento = 'Experiência informada de 1 ano e 7 meses no cargo de Encarregada de DP, concentrada em rotinas operacionais de DP completa; sem experiência no sistema Domínio e sem formação em Contabilidade. A prioridade é construir repertório técnico e prática supervisionada.',
               perfil_comportamental = '{"data_relatorio":"2026-09-11","disc":"S","disc_descritor":"Estabilidade e Suporte","descricao":"Descreve estabilidade, paciência, colaboração, escuta ativa, comunicação calma e diplomática, orientação a processos e atenção aos detalhes. Indica busca de consenso e manutenção da calma sob pressão.","complementares":"Como informações complementares, o relatório registra ISFJ e estilo Realizador. As oportunidades apontadas são abertura a mudanças e networking e visibilidade.","mbti":"ISFJ","estilo":"Realizador","oportunidades":"Abertura a mudanças e networking e visibilidade"}'::jsonb
         WHERE id = v_pdi;
    END IF;
END
$seed$;
